@js:
// 生成默认标题，最后兜底用，希望永远用不上
function buildDefaultTitle(url, index, maxPerPage = 60) {
    const pageNo = url.match(/_(\d+)/)?.[1] ?? 1;
    const num = (pageNo - 1) * maxPerPage + index + 1;
    return "第" + num + "章";
}

// 正则提取css ::after content
function getCssAfterTitle(pClass, sourceHtml) {
    if(!pClass || pClass?.isEmpty()) return "";
    const htmlStr = String(sourceHtml);
    const reg = new RegExp(pClass + "::after\\s*\\{[^}]*content\\s*:\\s*['\"](.*?)['\"]", "is");
    const match = htmlStr.match(reg);
    if (match) {
        let txt = match[1];
        txt = txt.replace(/\\(.)/g, "$1");
        return txt;
    }
    return "";
}

// ============= 主逻辑 =============
const list = java.getElements("#list-chapterAll dl dd a");
for(let i = 0; i < list.size(); i++){
    let aEl = list.get(i);
    let title = aEl.text().trim();

    // a无文本，尝试css伪元素
    if(title.isEmpty()){
        let pClassName = aEl.attr("class").replaceAll(".*(p_\\d+).*", "$1");
        title = getCssAfterTitle(pClassName, result);
    }

    // 仍取不到，生成默认标题
    if(!String(title)){
        title = buildDefaultTitle(baseUrl, i);
    }

    aEl.text(title)
}

